from collections import deque

def solve(grid):
    if not grid:
        return grid
    R = len(grid)
    C = len(grid[0])

    # Determine wall color: most frequent non-zero value in rows above the last (key) row
    freq = {}
    for r in range(R - 1):
        for val in grid[r]:
            if val != 0:
                freq[val] = freq.get(val, 0) + 1
    if not freq:
        return grid
    wall_color = max(freq, key=lambda k: freq[k])

    # Compute background: 0-cells reachable from the grid border
    bg = [[False] * C for _ in range(R)]
    q = deque()
    for r in range(R):
        for c in (0, C - 1):
            if grid[r][c] == 0 and not bg[r][c]:
                bg[r][c] = True
                q.append((r, c))
    for c in range(C):
        for r in (0, R - 1):
            if grid[r][c] == 0 and not bg[r][c]:
                bg[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and not bg[nr][nc] and grid[nr][nc] == 0:
                bg[nr][nc] = True
                q.append((nr, nc))

    visited = [[False] * C for _ in range(R)]
    empty_cavities = []   # (cells, (centroid_r, centroid_c))
    filled_cavities = []  # (cells, (centroid_r, centroid_c), color)

    for r in range(R):
        for c in range(C):
            if not visited[r][c] and not bg[r][c] and grid[r][c] != wall_color:
                # BFS to extract the connected component
                cells = []
                dq = deque()
                dq.append((r, c))
                visited[r][c] = True
                while dq:
                    cr, cc = dq.popleft()
                    cells.append((cr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < R and 0 <= nc < C and
                                not visited[nr][nc] and not bg[nr][nc] and
                                grid[nr][nc] != wall_color):
                            visited[nr][nc] = True
                            dq.append((nr, nc))
                # Skip components that touch the outer border (e.g., the key row)
                touches_border = any(cr == 0 or cr == R - 1 or cc == 0 or cc == C - 1
                                     for cr, cc in cells)
                if touches_border:
                    continue
                vals = [grid[cr][cc] for cr, cc in cells]
                n = len(cells)
                cent_r = sum(cr for cr, _ in cells) / n
                cent_c = sum(cc for _, cc in cells) / n
                if all(v == 0 for v in vals):
                    empty_cavities.append((cells, (cent_r, cent_c)))
                else:
                    # Assume uniform filled cavity
                    color = vals[0]
                    filled_cavities.append((cells, (cent_r, cent_c), color))

    if not empty_cavities or not filled_cavities:
        return grid

    out = [row[:] for row in grid]
    for cells_empty, (er, ec) in empty_cavities:
        best_color = filled_cavities[0][2]
        max_dist2 = -1.0
